begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000943','historic-owner@example.test'),('00000000-0000-4000-8000-000000000944','historic-other@example.test'),('00000000-0000-4000-8000-000000000945','historic-staff@example.test');
update public.profiles set role='admin' where id in('00000000-0000-4000-8000-000000000943','00000000-0000-4000-8000-000000000944');
create temp table import_payload(data jsonb);insert into import_payload values('[{"entity": "performance", "sheet": "RECAP BUDGET ", "row_number": 3, "raw": {"row_number": 3, "brand": "Brand A", "customer": "", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 10025, "budget_fw26": 20000, "orders_fw26": 15050, "budget_ss27": 30000, "orders_ss27": 25075}}, "mapped": {"row_number": 3, "brand": "Brand A", "customer": "", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 10025, "budget_fw26": 20000, "orders_fw26": 15050, "budget_ss27": 30000, "orders_ss27": 25075}}, "status": "valid", "messages": []}, {"entity": "performance", "sheet": "RECAP BUDGET ", "row_number": 4, "raw": {"row_number": 4, "brand": "Brand B", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 2000, "budget_fw26": 3000, "orders_fw26": 4000, "budget_ss27": 5000, "orders_ss27": 6000}}, "mapped": {"row_number": 4, "brand": "Brand B", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 2000, "budget_fw26": 3000, "orders_fw26": 4000, "budget_ss27": 5000, "orders_ss27": 6000}}, "status": "valid", "messages": []}, {"entity": "performance", "sheet": "RECAP BUDGET ", "row_number": 5, "raw": {"row_number": 5, "brand": "Brand escluso", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 99900, "budget_fw26": 90000, "orders_fw26": 80000, "budget_ss27": 70000, "orders_ss27": 60000}}, "mapped": {"row_number": 5, "brand": "Brand escluso", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 99900, "budget_fw26": 90000, "orders_fw26": 80000, "budget_ss27": 70000, "orders_ss27": 60000}}, "status": "valid", "messages": []}]'::jsonb);grant select on import_payload to authenticated;
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000943';
select public.start_import_batch('00000000-0000-4000-8000-000000000940','performance','historical.xlsx',repeat('a',64),100);
select public.start_import_batch('00000000-0000-4000-8000-000000000941','performance','missing.xlsx',repeat('b',64),100);
select public.start_import_batch('00000000-0000-4000-8000-000000000942','performance','null.xlsx',repeat('c',64),100);
insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000000940.xlsx','{"size":100}'),('imports','00000000-0000-4000-8000-000000000942.xlsx','{"size":100}');
select throws_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000941','{"pivotBrands":[]}','{}')$$,'23514','FILE_MISSING','configuration requires stored original');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'performance','same.xlsx',repeat('a',64),100)$$,'23505',null,'SQL serializes concurrent active file hashes');
select lives_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000940','{"pivotBrands":["Brand A","Brand B"]}','{"orders_ss26":12025}')$$,'configure original perimeter');
select lives_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940',data) from import_payload$$,'stage original records');
select lives_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940',data) from import_payload$$,'staging retry is idempotent');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000940'),3::bigint,'retry does not duplicate');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940','[]')$$,'23514','INVALID_CHUNK','empty chunk blocked');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940',(select jsonb_agg(data->0) from import_payload,generate_series(1,501)))$$,'23514','INVALID_CHUNK','chunk bounded to 500');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940',(select jsonb_build_array(jsonb_set(data->0,'{row_number}','6'),jsonb_set(data->0,'{row_number}','0')) from import_payload))$$,'23514',null,'failure halfway rolls whole chunk back');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000940'),3::bigint,'no partially staged row');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000944';
select throws_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000940')$$,'42501','FORBIDDEN','other admin cannot commit owner batch');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000940',data) from import_payload$$,'42501','FORBIDDEN','other admin cannot stage');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000943';
select lives_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000940')$$,'commit compares selected pivot only');
select lives_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000940')$$,'commit retry is idempotent');
select is((select stats->'totals'->>'orders_ss26' from public.import_batches where id='00000000-0000-4000-8000-000000000940'),'111925','batch stores complete source totals');
select is(public.performance_report('00000000-0000-4000-8000-000000000940','brand','{"brands":["Brand A","Brand B"]}')->'totals'->>'orders_ss26','12025','pivot perimeter totals');
select is(public.performance_report('00000000-0000-4000-8000-000000000940')->'totals'->>'orders_ss26','111925','all brands totals');
select is((public.performance_report('00000000-0000-4000-8000-000000000940')->>'group_count')::integer,3,'source brand not silently excluded');
select is((public.performance_report('00000000-0000-4000-8000-000000000940')->'totals'->>'unnamed_rows')::integer,1,'unnamed monetary row preserved');
select is((public.performance_report('00000000-0000-4000-8000-000000000940','area')->'groups'->0->>'customers')::integer,1,'unnamed records not invented as stores');
select is(public.performance_report('00000000-0000-4000-8000-000000000940','brand','{"search":"Brand escluso"}')->'totals'->>'orders_ss26','99900','search applies before aggregation');
select is((public.performance_report('00000000-0000-4000-8000-000000000940','brand','{"area":"MISSING"}')->'totals'->'orders_ss26'),'null'::jsonb,'empty result not zero');
select throws_ok($$select public.performance_report('00000000-0000-4000-8000-000000000940','unsafe')$$,'23514','INVALID_FILTERS','dimension whitelist');
select throws_ok($$select public.performance_report('00000000-0000-4000-8000-000000000940','brand','{"unsafe":true}')$$,'23514','INVALID_FILTERS','filter whitelist');
select lives_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000942','{"pivotBrands":[]}','{"orders_ss26":0}')$$,'configure null control');
select public.stage_import_rows('00000000-0000-4000-8000-000000000942','[{"entity": "performance", "sheet": "RECAP BUDGET ", "row_number": 3, "raw": {"row_number": 3, "brand": "Brand A", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": null, "budget_fw26": null, "orders_fw26": null, "budget_ss27": null, "orders_ss27": null}}, "mapped": {"row_number": 3, "brand": "Brand A", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": null, "budget_fw26": null, "orders_fw26": null, "budget_ss27": null, "orders_ss27": null}}, "status": "valid", "messages": []}]'::jsonb);
select throws_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000942')$$,'23514','TOTAL_DIFFERENCES','missing amount differs from expected zero');
select is((select status from public.import_batches where id='00000000-0000-4000-8000-000000000942'),'validated','failed comparison does not commit');
select is((select status from public.import_rows where batch_id='00000000-0000-4000-8000-000000000942'),'valid','failed comparison preserves staging');
select throws_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000942',null)$$,'23514','TOTAL_DIFFERENCES','null cannot confirm differences');
select lives_ok($$select public.complete_performance_import('00000000-0000-4000-8000-000000000942',true)$$,'explicit difference confirmation commits');
select is(public.performance_report('00000000-0000-4000-8000-000000000942')->'totals'->'orders_ss26','null'::jsonb,'confirmed missing stays null');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000945';
select throws_ok($$select public.performance_report('00000000-0000-4000-8000-000000000940')$$,'42501','FORBIDDEN','staff cannot read report');
select throws_ok($$select public.rollback_performance_import('00000000-0000-4000-8000-000000000940')$$,'42501','FORBIDDEN','staff cannot rollback');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000943';
select lives_ok($$select public.rollback_performance_import('00000000-0000-4000-8000-000000000940')$$,'rollback historical dataset');
select lives_ok($$select public.rollback_performance_import('00000000-0000-4000-8000-000000000940')$$,'rollback retry idempotent');
select throws_ok($$select public.performance_report('00000000-0000-4000-8000-000000000940')$$,'P0002','NOT_FOUND','rolled back dataset excluded');
reset role;
select ok(not app.valid_performance_row('{"row_number": 3, "brand": "Brand A", "customer": "Negozio", "representative": "Agente", "area": "EUROPE", "country": "IT", "region": "Lombardia", "city": "Milano", "customer_status": "Attivo", "values": {"orders_ss26": 0, "budget_fw26": 0, "orders_fw26": 0, "budget_ss27": 0, "orders_ss27": 0}}'::jsonb - 'row_number'),'missing source row number rejected');
select ok(exists(select 1 from public.audit_log where record_id='00000000-0000-4000-8000-000000000940' and action='update'),'state and audit written together');
select is((select count(*) from public.orders where import_batch_id in('00000000-0000-4000-8000-000000000940','00000000-0000-4000-8000-000000000942')),0::bigint,'historical import creates no invented orders');
select is((select count(*) from public.budgets where import_batch_id in('00000000-0000-4000-8000-000000000940','00000000-0000-4000-8000-000000000942')),0::bigint,'historical import creates no invented budget periods');
select * from finish();rollback;
